author:
Unknown;
   typikon reads the brand author from config.extra.author so feed
   subscribers see a real attribution.

   Inputs:
     config.extra.author.name — fallback brand author for entries
     config.extra.author.uri  — optional author URL
     page.extra.author        — per-entry override (becomes Person)
#}
{%- set author_name = config.extra.author?.name | default(value=config.title) -%}
{%- set author_uri = config.extra.author?.uri | default(value=config.base_url) -%}
{# Zola supplies `pages` for global, section, and taxonomy feeds after
   applying its date/render/hidden/include_in_feeds filter, deterministic
   feed ordering, and feed_limit. Preserve that engine-owned set unless a
   consumer explicitly assigns the root feed to one source section. Native
   section/taxonomy feeds always keep their supplied set. #}
{%- set_global feed_pages = pages -%}
{%- set_global feed_updated_pages = pages -%}
{%- set_global feed_title = config.title -%}
{%- set_global feed_subtitle = config.description -%}
{%- set_global feed_alternate = config.base_url -%}
{%- if term -%}
{%- set_global feed_title = config.title ~ " - " ~ term.name -%}
{%- elif section and section.title -%}
{%- set_global feed_title = config.title ~ " - " ~ section.title -%}
{%- endif -%}
{%- if config.extra.feed_source_section and not section and not term -%}
{%- set feed_source_path = config.extra.feed_source_section -%}
{%- if not (feed_source_path is ending_with(pat="_index.md")) -%}
{{ throw(message="atom.xml: feed source must name the canonical _index.md path, not a translated or leaf path: `" ~ feed_source_path ~ "`") }}
{%- endif -%}
{%- set feed_source = get_section(path=feed_source_path, lang=lang, allow_missing=true) -%}
{%- if not feed_source -%}
{{ throw(message="atom.xml: configured feed source section `" ~ feed_source_path ~ "` was not found") }}
{%- endif -%}
{%- set source_depth = feed_source_path | split(pat="/") | length -%}
{%- set native_feed_limit = pages | length -%}
{%- set_global scoped_pages = [] -%}
{%- for candidate in feed_source.pages -%}
{%- set candidate_depth = candidate.relative_path | split(pat="/") | length -%}
{# A colocated leaf bundle lives at /index.md but its physical parent
   is still the configured source section. Normalize that storage-only index
   segment before comparing depth; a nested transparent section remains one
   level deeper and is excluded. #}
{%- if candidate.colocated_path -%}
{%- set candidate_depth = candidate_depth - 1 -%}
{%- endif -%}
{%- if candidate.date and candidate.include_in_feeds and candidate_depth == source_depth -%}
{%- set_global scoped_pages = [...scoped_pages, candidate] -%}
{%- endif -%}
{%- endfor -%}
{%- if scoped_pages | length == 0 -%}
{{ throw(message="atom.xml: configured feed source section `" ~ feed_source_path ~ "` has no dated, feed-eligible direct pages") }}
{%- endif -%}
{# typikon-validate requires the configured owner section to sort by date.
   Preserve get_section().pages' native parsed-datetime/permalink ordering
   instead of re-sorting serialized RFC3339 strings in Tera. `pages | length`
   is the effective native feed_limit. Compute freshness over the full scope
   before slicing, as Zola does. #}
{%- set_global feed_updated_pages = scoped_pages -%}
{%- set_global feed_pages = scoped_pages[:native_feed_limit] -%}
{%- set_global feed_title = config.title ~ " - " ~ feed_source.title -%}
{%- set_global feed_subtitle = feed_source.description -%}
{%- set_global feed_alternate = feed_source.permalink -%}
{%- endif -%}

    {{ feed_title }}
    {%- if feed_subtitle %}
    {{ feed_subtitle }}
    {%- endif %}


    Zola
    {%- if feed_updated_pages | length > 0 -%}
    {# WHY a full scan instead of `sort(attribute="date") | last`: the
       feed's  must be the most recent EDIT across every entry,
       and one entry's most recent edit is `updated` when set, `date`
       otherwise (forkwright/typikon#92). Sorting by `date` alone and then
       reading THAT entry's `updated` misses an older-dated entry whose
       own `updated` is more recent than the newest-dated entry's own —
       exactly the case  exists to surface. set_global (not
       set) is required so an assignment inside the for loop survives
       past that iteration; date(format="%s") | int turns each value
       into an epoch integer because Tera's `>` only compares numbers,
       never date/string values directly. Zola serializes an unset
       `updated` as null, so Tera 2's default filter needs boolean=true
       to select the dated fallback for that falsey value. #}
    {%- set_global feed_updated_ts = 0 -%}
    {%- set_global feed_updated = "" -%}
    {%- for p in feed_updated_pages -%}
    {%- set p_updated = p.updated | default(value=p.date, boolean=true) -%}
    {%- set p_ts = p_updated | date(format="%s") | int -%}
    {%- if p_ts > feed_updated_ts -%}
    {%- set_global feed_updated_ts = p_ts -%}
    {%- set_global feed_updated = p_updated -%}
    {%- endif -%}
    {%- endfor -%}
    {%- else -%}
    {# No dated entries to derive updated from (e.g. a shop with no
       journal) — fall back to Zola's last_updated, then now(), to keep
       the feed valid. #}
    {%- set feed_updated = last_updated | default(value=now(), boolean=true) -%}
    {%- endif -%}
    {{ feed_updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
    {{ feed_url | safe }}

        {{ author_name }}
        {{ author_uri | safe }}

    {%- for page in feed_pages %}

        {{ page.title }}
        {{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
        {{ page.updated | default(value=page.date, boolean=true) | date(format="%Y-%m-%dT%H:%M:%S%:z") }}

            {{ page.extra.author | default(value=author_name) }}


        {{ page.permalink | safe }}
        {%- if page.summary %}
        {{ page.summary }}
        {%- elif page.description %}
        {{ page.description }}
        {%- endif %}
        {{ page.content }}

    {%- endfor %}
